using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "InspiredEffect", menuName = "Data/Battle/Effects/Moonie/Inspired Effect")]
public class LoseEffectEndOfTurnEffect : Effect
{
	[SerializeField]
	protected Effect effect;

	[SerializeField]
	private bool atTheEndOfPlayerTurn;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = (atTheEndOfPlayerTurn ? base.localizationManager.GetLocalizedAtTheEndOfYourTurn(withSpace: true) : base.localizationManager.GetLocalizedAtTheEndOfEnemiesTurn(withSpace: true));
		if (amount == EffectsValues.NO_VALUE || amount == EffectsValues.UNLOCKABLES_VALUE)
		{
			string localizedDescription = base.localizationManager.GetLocalizedDecreaseEffect(effect, GetNumberToReplaceWithX()).LowercaseFirst();
			return text + FormattedDescriptionReplacedWithX(localizedDescription);
		}
		return text + base.localizationManager.GetLocalizedDecreaseEffect(effect, amount).LowercaseFirst();
	}
}
